// pkg/util/paramtable/component_param.go line 2089-2118 (password length config)
p.MinPasswordLength = ParamItem{
    Key:          "proxy.minPasswordLength",
    DefaultValue: "6",  // ACTUAL MIN IS 6, NOT 8
    Version:      "2.0.0",
    PanicIfEmpty: true,
}
p.MinPasswordLength.Init(base.mgr)

p.MaxPasswordLength = ParamItem{
    Key:          "proxy.maxPasswordLength",
    DefaultValue: "72",  // ACTUAL MAX IS 72, NOT 64
    Version:      "2.0.0",
    Formatter: func(v string) string {
        n := getAsInt(v)
        if n > 72 {
            return "72"  // bcrypt max length
        }
        return v
    },
    PanicIfEmpty: true,
}
p.MaxPasswordLength.Init(base.mgr)

// internal/proxy/util.go line 1306-1313 (validation)
func ValidatePassword(password string) error {
    if len(password) < Params.ProxyCfg.MinPasswordLength.GetAsInt() || len(password) > Params.ProxyCfg.MaxPasswordLength.GetAsInt() {
        return merr.WrapErrParameterInvalidRange(
            Params.ProxyCfg.MinPasswordLength.GetAsInt(),
            Params.ProxyCfg.MaxPasswordLength.GetAsInt(),
            len(password), "invalid password length")
    }
    return nil
}

